"""Deterministic structural/semantic invariant check for the CVE-2019-15239 port.

Checks in the supplied include/net/tcp.h text:
  I1: exactly one definition of `static inline void tcp_init_send_head`.
  I2: that definition appears before `static inline void tcp_write_queue_purge`.
  I3: the body of tcp_write_queue_purge calls `tcp_init_send_head(sk)`.
  I4: no `tcp_chrono` symbol was introduced (4.4 has none).
  I5: the call is placed after `tcp_clear_all_retrans_hints(tcp_sk(sk))`.

Exit 0 = all invariants hold; exit 1 = at least one violated (vulnerable/negative).
Usage: semantic_check.py <path-to-tcp.h>
"""
import re
import sys


def body_of(text: str, signature: str) -> str:
    start = text.index(signature)
    brace = text.index("{", start)
    depth = 0
    for i in range(brace, len(text)):
        if text[i] == "{":
            depth += 1
        elif text[i] == "}":
            depth -= 1
            if depth == 0:
                return text[brace : i + 1]
    raise ValueError("unterminated body for " + signature)


def main() -> int:
    text = open(sys.argv[1], encoding="utf-8").read()
    failures = []

    init_sig = "static inline void tcp_init_send_head(struct sock *sk)"
    purge_sig = "static inline void tcp_write_queue_purge(struct sock *sk)"

    init_count = text.count(init_sig)
    if init_count != 1:
        failures.append(f"I1 exactly one tcp_init_send_head definition: found {init_count}")

    init_pos = text.find(init_sig)
    purge_pos = text.find(purge_sig)
    if init_pos < 0 or purge_pos < 0:
        failures.append("I2 could not locate both symbols")
    elif init_pos > purge_pos:
        failures.append("I2 tcp_init_send_head defined after tcp_write_queue_purge")

    if purge_pos >= 0:
        purge_body = body_of(text, purge_sig)
        if "tcp_init_send_head(sk)" not in purge_body:
            failures.append("I3 tcp_write_queue_purge does not call tcp_init_send_head(sk)")
        hints = "tcp_clear_all_retrans_hints(tcp_sk(sk));"
        if "tcp_init_send_head(sk)" in purge_body and hints in purge_body:
            if purge_body.index("tcp_init_send_head(sk)") < purge_body.index(hints):
                failures.append("I5 send_head reset precedes retrans-hint clearing")

    if "tcp_chrono" in text:
        failures.append("I4 tcp_chrono symbol introduced (absent in Linux 4.4)")

    if failures:
        print("SEMANTIC_CHECK=VIOLATED")
        for f in failures:
            print("  - " + f)
        return 1
    print("SEMANTIC_CHECK=OK (I1..I5 hold)")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

